mapper.update:
update monitor_notify_log
   set status = 'sent', success = true, sent_at = #{now}, error_msg = null, next_retry_at = null
 where id = #{id}
   and site_code = #{scope.siteCode}
   and status = 'pending'

update monitor_notify_log
   set retry_count = #{retryCount}, next_retry_at = #{nextRetryAt}, success = false,
       error_msg = #{error,jdbcType=VARCHAR}
 where id = #{id}
   and site_code = #{scope.siteCode}
   and status = 'pending'

update monitor_notify_log
   set status = 'failed', success = false, sent_at = #{now}, next_retry_at = null,
       error_msg = #{error,jdbcType=VARCHAR}
 where id = #{id}
   and site_code = #{scope.siteCode}
   and status = 'pending'

update monitor_event
   set notify_status = 'sent', notified_at = #{now}, notify_count = notify_count + 1, update_time = #{now}
 where event_id = #{eventId}
   and site_code = #{scope.siteCode}

update monitor_event
   set notify_status = #{status}, update_time = #{now}
 where event_id = #{eventId}
   and site_code = #{scope.siteCode}

update monitor_rule
   set last_notified_at = #{now}
 where rule_id = #{ruleId}
   and site_code = #{scope.siteCode}
